import pathlib,json,sys,subprocess,os,time,hashlib,re
base=pathlib.Path('/workspace/.proofs');snap=pathlib.Path('/workspace/.checkpoints/naming349');label=sys.argv[1];command=sys.argv[2:];assert command and not (base/(label+'.json')).exists();source=json.loads((snap/'snapshot.json').read_text());env={**os.environ,**json.loads((base/'native-test-env.json').read_text())};start=time.monotonic()
with (base/(label+'.log')).open('wb') as log:r=subprocess.run(command,cwd=pathlib.Path(source.get("compile_source_root",str(snap))),env=env,stdout=log,stderr=subprocess.STDOUT)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
log=(base/(label+'.log')).read_text();summaries=re.findall(r'test result: (?:ok|FAILED)\.[^\n]*',log);record={'label':label,'command':command,'exit':r.returncode,'seconds':time.monotonic()-start,'source':source,'uniform_source':all(sha(snap/name)==h and sha(pathlib.Path(source.get('compile_source_root',str(snap)))/name)==h for name,h in source['source'].items()),'summaries':summaries,'log_sha256':sha(base/(label+'.log'))};(base/(label+'.json')).write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({k:v for k,v in record.items() if k not in {'source','command'}}));print('\n'.join(line[:300] for line in log.splitlines()[-24:] if not line.startswith('{\"reason\":')));raise SystemExit(r.returncode or not record['uniform_source'])
